import{_ as a,c as t,o,ah as l}from"./chunks/framework.CKKOjZuE.js";const u=JSON.parse('{"title":"Syllable Annotation Guide","description":"","frontmatter":{},"headers":[],"relativePath":"SyllableAnnotation.md","filePath":"SyllableAnnotation.md","lastUpdated":1749679150000}'),i={name:"SyllableAnnotation.md"};function n(s,e,r,d,h,p){return o(),t("div",null,e[0]||(e[0]=[l('<h1 id="syllable-annotation-guide" tabindex="-1">Syllable Annotation Guide <a class="header-anchor" href="#syllable-annotation-guide" aria-label="Permalink to &quot;Syllable Annotation Guide&quot;">​</a></h1><p>This guide presents a general protocol for annotating MoSeq syllables.</p><h2 id="considerations-for-annotations" tabindex="-1">Considerations for Annotations <a class="header-anchor" href="#considerations-for-annotations" aria-label="Permalink to &quot;Considerations for Annotations&quot;">​</a></h2><p>Try to annotate using a set of simplified and reusable tags that describe multiple instance of each syllable, including locomotive status, head and nose position, location within the arena, as well as higher-order descriptions. For rears, consider if the rear is wall-assisted or not. Examples: paused, scanning, sniff; or nose-down, dart; or rear-up; etc.</p><h2 id="annotating-a-dataset" tabindex="-1">Annotating a Dataset <a class="header-anchor" href="#annotating-a-dataset" aria-label="Permalink to &quot;Annotating a Dataset&quot;">​</a></h2><ol><li><p>Load the MSQ file that you were tasked with annotating. For information on how to load your MSQ file, see the section <a href="/moseq-reports/UsingMoseq.html#loading-data">Loading a Data File</a> of the user guide.</p></li><li><p>Prepare your work area by adding any components, adjusting their size and position, and any component specific settings. You can alternatively load a MSL layout file (see the section <a href="/moseq-reports/UsingMoseq.html#loading-a-layout">Loading a Layout File</a>). For convenience, we have prepared a MSL layout file which is appropriate for this protocol, and is available <a href="https://drive.google.com/file/d/1vMijQ384Ex_vfkfFtETpvfH_P9NHBGaS/view?usp=sharing" target="_blank" rel="noreferrer">here</a>.</p></li><li><p>Within your main filter(typically <code>filter0</code>):</p><ol><li>Ensure that Count Method is set to Usage.</li><li>Ensure that Selected Syllable is set to 0.</li></ol></li><li><p>At this point, your screen should appear similar to the figure below: <br><img src="https://i.imgur.com/UjpfL94.png"></p></li><li><p>Now, for each MoSeq syllable do the following:</p><ol><li>Select the current syllable by changing the Selected Syllable to the next syllable to be annotated. (If this is the first syllable to be annotated, you may leave this set to 0).</li><li>Examine the Crowd Movies, Syllable Clips, and Spinogram components in order to garner an understanding of the behavioral ethology of the current syllable. <ul><li>Be sure to look at multiple individuals within the Crowd Movie. Reduce the playback speed if this is helpful.</li><li>Be sure to look at all examples available in the Syllable Clips. Observe the videos with and without the Only Syllable Subclip option enabled. Reduce the playback speed if this is helpful.</li><li>Be sure to look at all examples available in the Spinogram.</li></ul></li><li>Once satisfied with your impressions of the current syllable, place your annotations in the excel sheet.</li><li>Go back to step 5.1 and repeat for all syllables.</li></ol></li><li><p>Now, within your main filter (typically filter0), change the Count Method to Frames and change Selected Syllable to 0. Repeat step 5 while keeping the Count Method set to Frames until completed.</p></li></ol>',6)]))}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
